import { useState } from 'react';
import { useParams } from 'react-router';
import ImageModal from '../ImageModal';
import SectionParagraph from '../shared/SectionParagraph';
import allCharacters from './characterPageData/index';
import { StyledHeader } from '../styled';
import './characters.css';

import exterminatus from '../../assets/exterminatus.jpeg';

function CharacterPage() {
  const [imageInModal, setImageInModal] = useState(null);
  function closeModal() {
    setImageInModal(null);
  }
  function openModal(src, alt) {
    setImageInModal({ src, alt });
  }

  const params = useParams();
  const { characterId } = params;
  const character = allCharacters[characterId];
  if (!character) {
    return (
      <article>
        <StyledHeader>All records purged</StyledHeader>
        <img src={exterminatus} alt="" />
      </article>
    );
  }

  const {
    name, faction, associations, portrait, status, location,
    allies, enemies, activities, summary,
  } = character;

  const orkify = faction.identifier == 'Freebooter Orks';
  const alliesTitle = orkify ? 'Mates' : 'Allies';
  const enemiesTitle = orkify ? 'Gitz' : 'Enemies';
  const orkClass = orkify ? 'ork-h-font ork-color' : '';
  const orkSpeech = orkify ? 'ork-speech' : '';
  const orkLink = orkify ? 'ork-link' : '';

  return (
    <div className="article-page">
      {imageInModal ? <ImageModal closeModal={closeModal} image={imageInModal} /> : null}

      <h1 className="page-header">
        {
          orkify
            ? <span className="ork-color ork-h-font">{name}</span>
            : <span>+++{name}+++</span>
        }
      </h1>

      <section className="char-content">
        <aside role="region" className="infobox">
          <a className="image" role="button">
            <img
              className="infobox-image"
              src={portrait}
              alt={name}
              onClick={() => openModal(portrait, name)}
            />
          </a>
          <div className="infobox-data">
            <h3 className={`infobox-data-label ${orkClass}`}>Faction</h3>
            <div className="infobox-data-value">
              <a className={`site-link ${orkLink}`} href={`#/factions/${faction.id}`}>
                &gt;&gt;{faction.name}&lt;&lt;
              </a>
              {associations && associations.map(function(assoc, i) {
                return (
                  <>
                    <br />
                    <a className={`site-link ${orkLink}`} href={`#/factions/${assoc.id}`}>
                      &gt;&gt;{assoc.name}&lt;&lt;
                    </a>
                  </>
                )
              })}
            </div>
          </div>
          <div className="infobox-data">
            <h3 className={`infobox-data-label ${orkClass}`}>Origin</h3>
            <div className="infobox-data-value">
              <span className={orkSpeech}>{faction.identifier}</span>
            </div>
          </div>
          <div className="infobox-data">
            <h3 className={`infobox-data-label ${orkClass}`}>Status</h3>
            <div className="infobox-data-value">
              <span className={orkSpeech}>{status}</span>
            </div>
          </div>
          {
            location && <div className="infobox-data">
              <h3 className={`infobox-data-label ${orkClass}`}>Last Seen</h3>
              <div className="infobox-data-value">
                <a className={`site-link ${orkLink}`} href={`#/maps/${location.id}`}>
                  &gt;&gt;{location.name}&lt;&lt;
                </a>
              </div>
            </div>
          }
          {
            allies && <div className="infobox-data">
              <h3 className={`infobox-data-label ${orkClass}`}>{alliesTitle}</h3>
              <div className="infobox-data-value">
                {allies.map(function (ally, i) {
                  return (
                    <>
                      {i > 0 && <br />}
                      <a className={`site-link ${orkLink}`} href={`#/characters/${ally.id}`}>
                        &gt;&gt;{ally.name}&lt;&lt;
                      </a>
                    </>
                  );
                })}
              </div>
            </div>
          }
          {
            enemies && <div className="infobox-data">
              <h3 className={`infobox-data-label ${orkClass}`}>{enemiesTitle}</h3>
              <div className="infobox-data-value">
                {enemies.map(function (enemy, i) {
                  return (
                    <>
                      {i > 0 && <br />}
                      <a className={`site-link ${orkLink}`} href={`#/characters/${enemy.id}`}>
                        &gt;&gt;{enemy.name}&lt;&lt;
                      </a>
                    </>
                  );
                })}
              </div>
            </div>
          }
          {
            activities && <div className="infobox-data">
              <h3 className={`infobox-data-label ${orkClass}`}>Appearances</h3>
              <div className="infobox-data-value">
                {activities.map(function (event, i) {
                  return (
                    <>
                      {i > 0 && <br />}
                      <a className={`site-link ${orkLink}`} href={`#/events/${event.id}`}>
                        &gt;&gt;{event.date} {event.short}&lt;&lt;
                      </a>
                    </>
                  );
                })}
              </div>
            </div>
          }
        </aside>

        {summary.map(function (paragraph, index) {
          return (
            <SectionParagraph
              key={`paragraph-${index}`}
              className={orkSpeech}
              paragraph={paragraph}
              openModal={openModal}
            />
          );
        })}
      </section>
    </div>
  );
}

export default CharacterPage;